export function joiningType(cp: number): string {
  let lo = 0, hi = Joining.length / 15 - 1;
  while (lo <= hi) { const m = Math.floor((lo+hi)/2), p = m*5;
    if (cp < scalar(Joining,p)) hi = m-1;
    else if (cp > scalar(Joining,p+2)) lo = m+1;
    else return String.fromCharCode(unit(Joining,p+4)); }
  return 'U';
}
export function isModifier(cp: number): boolean {
  for (let p = 0; p < Modifiers.length/3; p += 4)
    if (cp >= scalar(Modifiers,p) && cp <= scalar(Modifiers,p+2)) return true;
  return false;
}
